const input = $('Extract from File').first().json.text;

// --- Utility to match optional field ---
function extractField(label) {
  const regex = new RegExp(label + ':?\\s*(.*)', 'i');
  return input.match(regex)?.[1]?.trim() || '';
}

// ✅ Extract Case Title
const caseTitle = input.match(/^([^\n]*?(v\.|V\.|In Re:).*?)\n/)?.[1]?.trim() || '';

// ✅ Full Jurisdiction (court header between Docket and "This case was retrieved on")
const jurisdictionMatch = input.match(/US District Court Docket\s*([\s\S]*?)This case was retrieved on/i);
const jurisdiction = jurisdictionMatch?.[1]?.replace(/\n/g, ' ').trim() || '';

// ✅ Proceeding Table Extraction
const proceedingsMatch = input.match(/Proceedings?\s*#?.*?\n([\s\S]*?)Copyright/i);
const rawProceedingText = proceedingsMatch?.[1]?.trim() || '';
const lines = rawProceedingText.split('\n').map(l => l.trim()).filter(Boolean);

const tableRows = [];
let currentRow = null;

for (const line of lines) {
  const match = line.match(/^(\d+)\s+(\d{2}\/\d{2}\/\d{4})\s+(.*)/);
  if (match) {
    if (currentRow) tableRows.push(currentRow);
    currentRow = {
      Number: match[1],
      Date: match[2],
      Description: match[3].trim()
    };
  } else if (currentRow) {
    currentRow.Description += ' ' + line;
  }
}
if (currentRow) tableRows.push(currentRow);

// ✅ Extract Participants Section
const participantsMatch = input.match(/Participants\s+Litigants Attorneys([\s\S]*?)\nDefendant\s+Proceedings/i);
const participantsBlock = participantsMatch?.[1]?.trim() || '';
const participantLines = participantsBlock.split('\n').map(l => l.trim()).filter(Boolean);

// ✅ Extract Plaintiff Names (from Participants > Litigants Attorneys section)
const plaintiffMatch = input.match(/Participants\s+Litigants Attorneys\s+([\s\S]*?)\nPlaintiff/i);
const plaintiffName = plaintiffMatch?.[1]?.trim() || '';
// ✅ Extract Defendant Names from lines before "Proceedings"
const beforeProceedingsMatch = input.match(/([\s\S]*?)Proceedings/i);
const beforeProceedingsBlock = beforeProceedingsMatch?.[1]?.trim() || '';
const beforeLines = beforeProceedingsBlock.split('\n').map(l => l.trim()).filter(Boolean);

const defendantNames = [];
for (let i = 0; i < beforeLines.length - 1; i++) {
  if (/^Defendant$/i.test(beforeLines[i + 1])) {
    const nameLine = beforeLines[i]?.trim();
    if (nameLine && !/ATTORNEY TO BE NOTICED/i.test(nameLine)) {
      defendantNames.push(nameLine);
    }
  }
}

// ✅ Extract Raw Attorney Blocks Only
// ✅ Extract Raw Attorney Blocks with newline formatting
const attorneys = [];
let currentBlock = [];
let insideAttorney = false;

for (let i = 0; i < participantLines.length; i++) {
  const line = participantLines[i];

  if (/ATTORNEY TO BE NOTICED/i.test(line)) {
    if (currentBlock.length > 0) {
      const formatted = currentBlock.join('\n');
      attorneys.push(formatted);
      currentBlock = [];
    }
    currentBlock.push(participantLines[i - 1] || '');
    currentBlock.push(line);
    insideAttorney = true;
    continue;
  }

  if (insideAttorney) {
    currentBlock.push(line);
    if (/Email:/i.test(line)) {
      const formatted = currentBlock.join('\n');
      attorneys.push(formatted);
      currentBlock = [];
      insideAttorney = false;
    }
  }
}
if (currentBlock.length > 0) {
  const formatted = currentBlock.join('\n');
  attorneys.push(formatted);
}
// ✅ Final Output
return {
  json: {
    "Case Title": caseTitle,
    "Case Number": extractField("Case Number"),
    "Date Filed": extractField("Date Filed"),
    "Assigned To": extractField("Assigned To"),
    "Nature of Suit": extractField("Nature of Suit"),
    "Cause": extractField("Cause"),
    "Jurisdiction": jurisdiction,
    "Court": "United States District Court",
    "Demand Amount": input.match(/Demand Amount:\s*\$?([\d,]+)/)?.[1]?.trim() || '0',
    "Plaintiff Names": plaintiffName,
    "Defendant Names": defendantNames,
    "Attorneys": attorneys,
    "Proceeding Table": tableRows
  }
};

const raw = ($('Extract from File').first().json.text || "")
  .replace(/\r/g, "")
  .replace(/[ \t]+\n/g, "\n")
  .trim();

const norm = s => (s || "").replace(/\s+/g, " ").trim();
const linesOf = s => (s || "").split("\n").map(l => l.trim()).filter(Boolean);

// 1) Slice: after first "Litigants Attorneys" and BEFORE "Proceedings"
function sliceParticipants(txt) {
  const start =
    txt.match(/Participants\s*(?:\n+| )Litigants\s+Attorneys\s*\n/i) ||
    txt.match(/Litigants\s+Attorneys\s*\n/i);
  if (!start) return "";
  const after = txt.slice(start.index + start[0].length);
  const end = after.match(/^\s*Proceedings\b/im);
  return (end ? after.slice(0, end.index) : after).trim();
}

// 2) Parties extractor (Movant is treated as Plaintiff)
function extractParties(block) {
  const lines = linesOf(block);
  const plaintiffs = new Set();
  const defendants = new Set();
  const roleRe = /^(Plaintiff|Defendant|Movant)\b/i;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // A) Same line: "Name — Role"
    const same = line.match(/(.+?)\s*[-–—]\s*(Plaintiff|Defendant|Movant)\b/i);
    if (same) {
      const name = norm(same[1]);
      const role = same[2].toLowerCase();
      if (role.startsWith("plaintiff") || role.startsWith("movant")) plaintiffs.add(name);
      else if (role.startsWith("defendant")) defendants.add(name);
      continue;
    }

    // B) Role line then name on NEXT line
    if (roleRe.test(line) && lines[i + 1]) {
      const role = line.toLowerCase();
      const name = norm(lines[i + 1]);
      if (role.startsWith("plaintiff") || role.startsWith("movant")) plaintiffs.add(name);
      else if (role.startsWith("defendant")) defendants.add(name);
      continue;
    }

    // C) Name line then role on NEXT line
    if (lines[i + 1] && roleRe.test(lines[i + 1])) {
      const role = lines[i + 1].toLowerCase();
      const name = norm(line);
      if (role.startsWith("plaintiff") || role.startsWith("movant")) plaintiffs.add(name);
      else if (role.startsWith("defendant")) defendants.add(name);
      continue;
    }
  }

  return { plaintiffs: [...plaintiffs], defendants: [...defendants] };
}

// 3) STRICT attorney parser matching your pattern
function parseAttorneys(block) {
  const L = linesOf(block);
  // primary starts = exact marker lines
  let starts = [];
  for (let i = 0; i < L.length; i++) {
    if (/^ATTORNEY\s+TO\s+BE\s+NOTICED$/i.test(L[i])) starts.push(i);
  }
  // fallback: if no markers, allow Email:-based guessing
  if (!starts.length) {
    for (let i = 0; i < L.length; i++) {
      if (/^Email:/i.test(L[i]) && i > 0) starts.push(i - 1);
    }
  }
  if (!starts.length) return [];

  // sort & dedupe
  starts = [...new Set(starts)].sort((a, b) => a - b);

  const attorneys = [];
  for (let s = 0; s < starts.length; s++) {
    const mark = starts[s];
    const nextMark = s < starts.length - 1 ? starts[s + 1] : L.length;

    // NAME = line above the marker (or the start)
    const name = norm(L[mark - 1] || "NA");

    // FIRM = first non-empty line after marker
    let firm = "NA";
    let firmLine = mark + 1;
    while (firmLine < nextMark && !norm(L[firmLine])) firmLine++;
    if (firmLine < nextMark) firm = norm(L[firmLine]);

    // ADDRESS = subsequent lines until Phone/Fax/Email/next marker/role
    const stopRe = /(Email:|Fax:|Phone:|\(\d{3}\)\s*\d{3}-\d{4}|\b\d{3}[-.\s]\d{3}[-.\s]\d{4}\b|^ATTORNEY\s+TO\s+BE\s+NOTICED$|^(Plaintiff|Defendant|Movant)\b)/i;
    const addressLines = [];
    let i = firmLine + 1;
    while (i < nextMark && !stopRe.test(L[i])) {
      const line = norm(L[i]);
      if (line) addressLines.push(line);
      i++;
    }
    const address = addressLines.length ? addressLines.join(", ") : "NA";

    // CONTACTS within this block
    let phone = "NA";
    let email = "NA";
    for (let j = firmLine + 1; j < nextMark; j++) {
      const line = L[j] || "";
      // phone
      const p = line.match(/\(\d{3}\)\s*\d{3}-\d{4}|\b\d{3}[-.\s]\d{3}[-.\s]\d{4}\b/);
      if (p && phone === "NA") phone = p[0].trim();
      // email
      if (/Email:/i.test(line) || /@/.test(line)) {
        const m = line.match(/Email:\s*([^\s;]+)/i) || line.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
        if (m) email = (m[1] || m[0]).trim().toLowerCase();
      }
    }

    // represents inferred from nearby lines (Movant => Plaintiff)
    let represents = "Unknown";
    const winStart = Math.max(0, mark - 3);
    const winEnd = Math.min(L.length, mark + 4);
    const windowTxt = L.slice(winStart, winEnd).join(" ");
    if (/\bPlaintiff\b/i.test(windowTxt) || /\bMovant\b/i.test(windowTxt)) represents = "Plaintiff";
    else if (/\bDefendant\b/i.test(windowTxt)) represents = "Defendant";

    const rawBlock = [
      name,
      "ATTORNEY TO BE NOTICED",
      firm !== "NA" ? firm : null,
      ...addressLines,
      phone !== "NA" ? phone : null,
      email !== "NA" ? `Email:${email}` : null
    ].filter(Boolean).join("\n");

    attorneys.push({
      name: name || "NA",
      firm,
      role: "ATTORNEY TO BE NOTICED",
      email,
      phone,
      address,
      represents,
      raw: rawBlock
    });
  }

  return attorneys;
}

// 4) EXTRA plaintiff harvesting around "ATTORNEY TO BE NOTICED" markers
function harvestPlaintiffsNearMarkers(block) {
  const lines = linesOf(block);
  const harvested = new Set();
  const roleRe = /^(Plaintiff|Defendant|Movant)\b/i;

  for (let i = 0; i < lines.length; i++) {
    if (!/^ATTORNEY\s+TO\s+BE\s+NOTICED$/i.test(lines[i])) continue;

    // scan backwards up to 6 lines for a role, take the line ABOVE as the party name
    for (let k = i - 1; k >= Math.max(0, i - 6); k--) {
      if (roleRe.test(lines[k])) {
        const role = lines[k].toLowerCase();
        const nameLine = (k - 1 >= 0) ? norm(lines[k - 1]) : "";
        if (!nameLine) break;

        if (role.startsWith("plaintiff") || role.startsWith("movant")) harvested.add(nameLine);
        break;
      }
    }
  }
  return [...harvested];
}

// 5) Second "Litigants Attorneys" fallback to find Defendant
function secondBlockDefendant(txt) {
  const re = /Litigants\s+Attorneys\s*\n/gi;
  const starts = [];
  let m;
  while ((m = re.exec(txt)) !== null) {
    starts.push(m.index + m[0].length);
    if (starts.length > 5) break;
  }
  if (starts.length < 2) return null;

  const afterSecond = txt.slice(starts[1]);
  const end = afterSecond.match(/^\s*Proceedings\b/im);
  const block = (end ? afterSecond.slice(0, end.index) : afterSecond).trim();
  const lines = linesOf(block);

  let atIdx = lines.findIndex(l => /^ATTORNEY\s+TO\s+BE\s+NOTICED$/i.test(l));
  if (atIdx === -1) atIdx = lines.findIndex(l => /^Email:/i.test(l));

  for (let i = 0; i < (atIdx === -1 ? lines.length : atIdx); i++) {
    const same = lines[i].match(/(.+?)\s*[-–—]\s*(Defendant)\b/i);
    if (same) return norm(same[1]);
    if (/^Defendant\b/i.test(lines[i]) && lines[i + 1]) return norm(lines[i + 1]);
    if (lines[i + 1] && /^Defendant\b/i.test(lines[i + 1])) return norm(lines[i]);
  }
  if (atIdx > 0) return norm(lines[atIdx - 1]);
  return null;
}

// ---- RUN ----
const participants_block = sliceParticipants(raw);

// parties from role patterns
const { plaintiffs, defendants } = extractParties(participants_block);

// attorneys parsed strictly
const attorneys = parseAttorneys(participants_block);
const attorneyNamesSet = new Set(attorneys.map(a => a.name.toLowerCase()));

// extra plaintiff candidates harvested around markers
const harvestedPlaintiffs = harvestPlaintiffsNearMarkers(participants_block);

// combine + dedupe plaintiffs (Movant already mapped to Plaintiff)
let plaintiff_names = [...new Set([...plaintiffs, ...harvestedPlaintiffs].map(norm))];

// remove any attorney names from plaintiffs
plaintiff_names = plaintiff_names.filter(n => !attorneyNamesSet.has(n.toLowerCase()));

// defendants
let defendant_names = [...new Set(defendants.map(norm))];

// if no defendant found, try the second-block rule
if (!defendant_names.length) {
  const def2 = secondBlockDefendant(raw);
  if (def2) defendant_names.push(def2);
}

// ensure non-empty arrays
if (!plaintiff_names.length) plaintiff_names = ["NA"];
if (!defendant_names.length) defendant_names = ["NA"];

return [
  {
    json: {
      participants_block,
      plaintiff_names,
      defendant_names,
      attonery: { list: attorneys, count: attorneys.length }
    }
  }
];

function extractLexisDocketLinks(text) {
  if (!text) return [];

  // Regex: match only links that start with https://advance.lexis.com/api/docket?
  const regex = /https:\/\/advance\.lexis\.com\/api\/docket\?[^\s"]+/gi;

  const matches = text.match(regex);
  return matches ? matches : [];
}

// Get the input text from Gmail Trigger
const sampleText = $('Gmail Trigger').first().json.text;

// Extract only LexisNexis docket links
const links = extractLexisDocketLinks(sampleText);

// Return as n8n output
return [
  {
    json: {
      links,                    // array of only Lexis docket links
      first_link: links[0] || 'NA'  // first one only, or NA
    }
  }
];

// --------------------------------------------------
// Get HTML email body safely
// --------------------------------------------------
const html =
  $('Gmail Trigger').first()?.json?.html ||
  $('Gmail Trigger').first()?.json?.textAsHtml ||
  $('Gmail Trigger').first()?.json?.text ||
  "";

// --------------------------------------------------
// Helpers
// --------------------------------------------------
function clean(text) {
  if (!text) return "N/A";
  return text
    .replace(/<a[^>]*>(.*?)<\/a>/gi, "$1")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// --------------------------------------------------
// Regex to extract rows and cells
// --------------------------------------------------
const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
const cellRegex = /<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/gi;

let data = [];
let rowMatch;

// --------------------------------------------------
// Parse table rows
// --------------------------------------------------
while ((rowMatch = rowRegex.exec(html)) !== null) {
  let cells = [];
  let cellMatch;

  while ((cellMatch = cellRegex.exec(rowMatch[1])) !== null) {
    cells.push(clean(cellMatch[1]));
  }

  // Skip header or malformed rows
  if (
    cells.length < 9 ||
    cells[0].toLowerCase().includes("docket")
  ) {
    continue;
  }

  data.push({
    docket_number: cells[0],
    case_name: cells[1],
    court: cells[2],
    participant: cells[3],
    description: cells[4],
    nature_of_suit: cells[5],
    complaint: cells[6],
    date_hit: cells[7],
    date_filed: cells[8],
  });
}

// --------------------------------------------------
// Return wrapped structure (NO data0)
// --------------------------------------------------
return [
  {
    json: {
      data
    }
  }
];

// ---------- Helpers ----------
function toDate(raw) {
  if (raw === undefined || raw === null || raw === "") return "N/A";
  const s = String(raw).trim();
  const n = Number(s);
  if (!Number.isFinite(n)) {
    const m = s.match(/^\d{4}-\d{2}-\d{2}/);
    return m ? m[0] : s;
  }
  const ms = s.length >= 13 ? n : Math.floor(n) * 1000;
  const d = new Date(ms);
  return isNaN(d.getTime()) ? "N/A" : d.toISOString().slice(0, 10);
}

function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== "") return v;
  }
  return "N/A";
}

// ---------- Get docket data robustly ----------
const first = $input.first()?.json || {};
let dockets = [];

if (Array.isArray(first.data1)) {
  dockets = first.data1;
} else if (Array.isArray(first.data)) {
  dockets = first.data;
} else {
  dockets = $input.all().map(i => i.json || {});
}

// ---------- Build table rows ----------
let rows = "";

dockets.forEach((d, index) => {
  const docketNo = firstNonEmpty(d["Docket #"], d.docket_number);
  const caseName = firstNonEmpty(d["Case Name"], d.case_name);
  const court = firstNonEmpty(d.Court, d.court);
  const participant = firstNonEmpty(d.Participant, d.participant);
  const description = firstNonEmpty(d.Description, d.description);
  const nature = firstNonEmpty(d["Nature of Suit"], d.nature_of_suit);
  const complaint = firstNonEmpty(d.Complaint, d.complaint);
  const dateHit = toDate(firstNonEmpty(d["Date Hit"], d.date_hit));
  const dateFiled = toDate(firstNonEmpty(d["Date filed"], d.date_filed));

  rows += `
    <tr>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${index + 1}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${docketNo}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${caseName}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${court}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${participant}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${description}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${nature}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${complaint}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${dateHit}</td>
      <td style="padding:8px; border:1px solid #ddd; font-size:13px;">${dateFiled}</td>
    </tr>
  `;
});

// ---------- Build full HTML ----------
const html = `
<!DOCTYPE html>
<html>
  <body style="font-family: Arial, sans-serif; color:#222;">
    <h2 style="font-size:18px; margin-bottom:6px;">📄 Daily LexisAlert Table</h2>
    <p style="font-size:13px; margin-top:0; margin-bottom:14px;">
      Below is the summary of docket activity extracted from incoming emails.
    </p>

    <table cellpadding="0" cellspacing="0" width="100%"
      style="border-collapse:collapse; border:1px solid #ddd;">
      <thead>
        <tr style="background-color:#f5f5f5;">
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">#</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Docket #</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Case Name</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Court</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Participant</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Description</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Nature of Suit</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Complaint</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Date Hit</th>
          <th style="padding:8px; border:1px solid #ddd; font-size:12px;">Date Filed</th>
        </tr>
      </thead>
      <tbody>
        ${
          rows.trim()
            ? rows
            : `<tr>
                 <td colspan="10" style="padding:8px; border:1px solid #ddd; font-size:13px; text-align:center;">
                   No new docket activity found.
                 </td>
               </tr>`
        }
      </tbody>
    </table>
  </body>
</html>
`;

// ---------- Return for Gmail / Teams ----------
return [{ json: { html } }];

return $input.all().map(item => { const data = { ...item.json }; // Remove the key 
if ("count_row_number" in data) { delete data.count_row_number; } // Return cleaned item
                                return { json: data }; });
